// Package toollog records every request burpsy made or relayed — Repeater, Intruder,
// Scanner, Sequencer, the crawler and the proxy listener — as one ordered log. That
// coverage is Burp Logger's own identity (tools/logger/index.html): "Burp Logger records
// all the HTTP traffic that Burp Suite generates in real-time. […] By default, Logger
// displays traffic generated by all the tools in Burp Suite. This includes modified
// requests, and requests sent by extensions. By contrast, the HTTP history only displays
// traffic from a browser that is proxied through Burp."
//
// Kept separate from proxy history in the sense that matters — the bytes live in the
// TrafficStore and a row holds only metadata plus the exchange id they sit under, so the
// log is not a second copy of the memory Burp bounds with its capture limit. It is not
// separate in coverage: proxied browser traffic is a tool's traffic here, not an exclusion
// (burpsy-react-ui-6dt). Mirrors the Rust burpsy-tools logger module.
package toollog

import (
	"fmt"
	"regexp"
	"strings"
	"sync"
	"sync/atomic"
	"time"

	"github.com/burpsy-go/burpsy/internal/core"
)

// Tool identifies which tool sent a request.
//
// ToolProxy is the proxy listener's own traffic — what the operator's client sent through
// this proxy. It belongs here for the reason Burp's Logger has a Proxy entry in its capture
// filter's per-tool axis: the page's subject is what the suite did, and the listener is part
// of the suite. A log that omitted it was a narrower "tool log" whose exclusion was
// undeclared rather than chosen (burpsy-react-ui-6dt); including it with the same capture
// toggle every other tool has is the switch Burp's operator gets.
type Tool int

const (
	ToolRepeater Tool = iota
	ToolIntruder
	ToolScanner
	ToolSequencer
	ToolComparer
	ToolSession
	ToolDecoder
	// ToolCrawler is the crawler's own fetches. Appended at the end rather than
	// slotted in alphabetically because the ordinal is what the durable mirror
	// stores: inserting a variant would relabel every persisted row above it.
	ToolCrawler
	// ToolProxy is traffic the proxy listener relayed for the operator's own client
	// (burpsy-react-ui-6dt). Appended for the same durability reason as ToolCrawler: the
	// ordinal is what the durable mirror stores, so a new variant goes on the end and never
	// in the middle.
	ToolProxy
)

// ToolAll is every tool, so a caller can build a per-tool histogram without
// hard-coding the set — the reason a filter that pre-seeds its own list of tool
// names silently reported zero for any tool added after it was written.
var ToolAll = [9]Tool{
	ToolRepeater,
	ToolIntruder,
	ToolScanner,
	ToolSequencer,
	ToolComparer,
	ToolSession,
	ToolDecoder,
	ToolCrawler,
	ToolProxy,
}

func (t Tool) String() string {
	switch t {
	case ToolRepeater:
		return "repeater"
	case ToolIntruder:
		return "intruder"
	case ToolScanner:
		return "scanner"
	case ToolSequencer:
		return "sequencer"
	case ToolComparer:
		return "comparer"
	case ToolSession:
		return "session"
	case ToolDecoder:
		return "decoder"
	case ToolCrawler:
		return "crawler"
	case ToolProxy:
		return "proxy"
	default:
		return "unknown"
	}
}

// ToolFromName resolves a tool name (as Tool.String produces) back to its
// Tool, for wire round-trips that must speak names not ordinals. The second
// return is false for "unknown" and for any other unrecognised string, so a
// caller can refuse rather than silently mis-record.
func ToolFromName(name string) (Tool, bool) {
	for _, t := range ToolAll {
		if t.String() == name {
			return t, true
		}
	}
	return Tool(0), false
}

// Entry is one record in the tool log.
type Entry struct {
	ID     uint64
	Tool   Tool
	Host   string
	Port   uint16
	TLS    bool
	Method string
	Path   string
	Status int
	// ResponseLen is how many response bytes came back, or nil when this row has no single response to
	// measure: a send that failed at the transport received nothing, and a row that stands for a whole
	// run (an intruder attack, an audit) does not correspond to one response at all.
	//
	// A pointer because 0 and "there wasn't one" are different facts. The field did not exist until
	// now, and the wire projection filled it with a hardcoded 0 for every row, so Logger's Length
	// column read as "every response was empty" — the single worst reading for the pane an operator
	// uses to reconcile what a tool sent against what came back. Never widen this back to a plain int:
	// the zero is precisely the lie being removed.
	ResponseLen *int
	StartedMs   uint64
	DurationMs  uint64
	Note        string
	// Comment is the operator's annotation (burpsy-react-ui-5da): Burp's log comment,
	// distinct from Note, which producers write (errors and run summaries) and the wire
	// surfaces as the row's error text. Merging the two would let an annotation overwrite
	// the reason a send failed, or a failure overwrite an annotation.
	Comment string
	// Highlight is the operator's colour tag for this row (burpsy-react-ui-5da), empty when
	// unset. It reuses core.ValidHighlights' vocabulary — the same colour means the same thing
	// in Logger, Organizer and HTTP history — rather than a second vocabulary, and validation
	// lives at the API boundary (toolLogSetComment) for the same reason the organizer's does.
	Highlight string
	// Exchange is the traffic-store exchange this row came from, or nil when the row has no bytes
	// to show: a transport failure received nothing to store, and a row standing for a whole run
	// (an audit) is not one exchange. Nil is also every row recorded before the link existed —
	// those rows stay metadata-only rather than pretending.
	//
	// Logger's message viewer resolves bytes through this link on demand (the same
	// exchange-id-then-fetch pattern the organizer uses), so no request/response copy is stored
	// here: the traffic store already holds the bytes once, and a second copy would double the
	// memory Burp manages with its explicit capture limit.
	Exchange *core.ExchangeID
}

// Bytes wraps a measured response length for Record's respLen argument. Callers that received no
// response pass nil instead, and keeping that spelling visible at every call site is the point — see
// Entry.ResponseLen.
func Bytes(n int) *int { return &n }

// ToolLog is a bounded, oldest-first-evicting log of tool activity.
//
// It carries two independent axes, and they must not be collapsed into one:
// the **capture** axis decides which tools' requests are recorded at all, and
// the display axis (the caller's filter over All()) decides what is shown.
// The distinction is Burp Logger's Zfp2 model and it is not cosmetic: capture
// is destructive — a request refused here is gone forever, because no bytes
// were kept — while hiding a row is reversible. A UI that presented "stop
// showing scanner rows" as the same control as "stop recording scanner
// requests" would let an operator believe unrecorded traffic could be
// un-hidden later. See the uncaptured counters below for how the loss is
// reported rather than hidden.
type ToolLog struct {
	mu       sync.RWMutex
	entries  []*Entry
	capacity int
	dropped  uint64
	nextID   uint64

	// capturing is the capture axis as a bitmask over tool ordinals: bit t set
	// means Tool(t)'s Record calls store an entry; clear means they are
	// refused. Atomic rather than lock-held because Record sits on the path of
	// every request any tool sends (see OnChange) and the read must stay a
	// single word load there. Every tool captures by default — the zero value
	// of this field would mean nothing records, so New seeds it explicitly.
	capturing atomic.Uint32

	// filter narrows which records Record keeps, beyond the per-tool capture axis
	// (burpsy-react-ui-72k9): status buckets, a search term over method/host/path, and an
	// in-scope-only switch. Destructive like the tool axis — a refused record is sent and
	// deliberately not kept — so it reads and writes under the same lock as the entries
	// rather than through a lock-free snapshot that could disagree mid-record.
	filter CaptureFilter
	// filtered counts what the filter refused. Beside Uncaptured, never merged into it:
	// "not this tool" and "not this traffic" are different reasons to lose a row.
	// Atomic because Record's refusal path must not take the entries lock to count.
	filtered atomic.Uint64
	// scope answers the in-scope question for ScopeOnly. Nil means no scope was attached,
	// and a nil scope filters nothing — the intercept engine's fail-safe, for the same
	// reason: an attached-but-unreadable scope must not silently empty the log.
	scope ScopeChecker
	// uncaptured counts, per tool ordinal, the Record calls capture refused.
	// This is the honest-counting counterpart of the axis: switching a tool's
	// capture off must not look like an empty log — it looks like a log plus a
	// number of requests that were sent and deliberately not kept. Like
	// Dropped, these survive Clear (clearing the buffer does not un-send the
	// traffic it no longer describes) and reset on Restore (a snapshot carries
	// no such history to restore).
	uncaptured [len(ToolAll)]atomic.Uint64

	// onRecord is an optional write-through hook (see SetPersistenceSink). It
	// runs under the lock, must not call back into the log, and must not fail
	// the in-memory record.
	onRecord func(e *Entry)
	// onChange is an optional signal that the log changed at all (see OnChange).
	// Separate from onRecord because the two have different owners — that one is
	// the durable mirror's single slot — and because this one also fires for a
	// clear, which a live pane has to hear about as much as an arrival.
	onChange func()
}

const DefaultCapacity = 100000

// captureAll is every tool-ordinal bit set: the seed New applies so the zero
// value of an unseeded log cannot mean "record nothing". 1<<n - 1 sets the low
// n bits, which is exactly the nine tool ordinals.
const captureAll = uint32(1)<<len(ToolAll) - 1

func New() *ToolLog {
	l := &ToolLog{capacity: DefaultCapacity}
	l.capturing.Store(captureAll)
	return l
}

// ScopeChecker is the engagement scope, narrowed to the one question the capture filter
// asks. Mirrors intercept.ScopeChecker so neither package imports the other for one method.
type ScopeChecker interface {
	Contains(host string, port uint16, path string, isTLS bool) bool
}

// SearchSpec is a capture-time search over method, host and path.
type SearchSpec struct {
	Term          string
	Regex         bool
	CaseSensitive bool
	Negate        bool

	re *regexp.Regexp
}

// CaptureFilter narrows Record beyond the per-tool axis. The zero value filters nothing,
// so a log that never had a filter set behaves exactly as before.
type CaptureFilter struct {
	// Status holds accepted status classes (2-5, first digit); empty accepts all.
	Status []int
	Search SearchSpec
	// ScopeOnly keeps in-scope traffic. Needs a scope via SetScope; without one it is
	// inert rather than emptying the log.
	ScopeOnly bool
}

// compile validates the search term the way rules are validated: a bad regex is refused
// when the filter is saved, not per record. Called with the term this filter carries.
func (f *CaptureFilter) compile() error {
	if f.Search.Term == "" || !f.Search.Regex {
		f.Search.re = nil
		return nil
	}
	re, err := regexp.Compile(f.Search.Term)
	if err != nil {
		return err
	}
	f.Search.re = re
	return nil
}

// matches reports whether one record survives the filter. Scope is passed in because it
// lives on the log, not in the filter value.
func (f *CaptureFilter) matches(host string, port uint16, tls bool, method, path string, status int, scope ScopeChecker) bool {
	if len(f.Status) > 0 {
		hit := false
		for _, class := range f.Status {
			if status/100 == class {
				hit = true
				break
			}
		}
		if !hit {
			return false
		}
	}
	if f.ScopeOnly {
		if scope == nil {
			return true
		}
		if !scope.Contains(host, port, path, tls) {
			return false
		}
	}
	if f.Search.Term != "" {
		haystack := method + " " + host + " " + path
		term := f.Search.Term
		if !f.Search.CaseSensitive {
			haystack = strings.ToLower(haystack)
			term = strings.ToLower(term)
		}
		var hit bool
		if f.Search.re != nil {
			target := haystack
			if f.Search.CaseSensitive {
				target = method + " " + host + " " + path
			}
			hit = f.Search.re.MatchString(target)
		} else {
			hit = strings.Contains(haystack, term)
		}
		if hit == f.Search.Negate {
			return false
		}
	}
	return true
}

func (l *ToolLog) WithCapacity(c int) *ToolLog {
	l.mu.Lock()
	l.capacity = c
	l.mu.Unlock()
	return l
}

// SetCapacity changes the bound at runtime (burpsy-react-ui-72k9): Burp's capture limit.
// Non-positive values are refused rather than clamped — a limit of zero would read as
// "keep nothing" while meaning "unlimited" nowhere.
func (l *ToolLog) SetCapacity(c int) error {
	if c <= 0 {
		return fmt.Errorf("capacity must be positive, got %d", c)
	}
	l.mu.Lock()
	l.capacity = c
	for len(l.entries) > l.capacity {
		l.entries = l.entries[1:]
		l.dropped++
	}
	l.mu.Unlock()
	if l.onChange != nil {
		l.onChange()
	}
	return nil
}

// Capacity reports the current bound.
func (l *ToolLog) Capacity() int {
	l.mu.RLock()
	defer l.mu.RUnlock()
	return l.capacity
}

// ScopeAttached reports whether ScopeOnly can filter. Read by the API so the page can
// disable the switch with its reason instead of offering a control that does nothing.
func (l *ToolLog) ScopeAttached() bool {
	l.mu.RLock()
	defer l.mu.RUnlock()
	return l.scope != nil
}

// SetScope attaches the engagement scope for ScopeOnly filtering.
func (l *ToolLog) SetScope(s ScopeChecker) {
	l.mu.Lock()
	l.scope = s
	l.mu.Unlock()
}

// SetFilter replaces the capture filter, compiling its regex first so a bad pattern is
// refused at save time with the previous filter still in force — never a half-applied one.
func (l *ToolLog) SetFilter(f CaptureFilter) error {
	if err := f.compile(); err != nil {
		return err
	}
	l.mu.Lock()
	l.filter = f
	l.mu.Unlock()
	if l.onChange != nil {
		l.onChange()
	}
	return nil
}

// Filter returns the capture filter in force.
func (l *ToolLog) Filter() CaptureFilter {
	l.mu.RLock()
	defer l.mu.RUnlock()
	return l.filter
}

// Filtered counts records the filter refused. Beside Dropped and Uncaptured: three different
// reasons to lose a row, three counters, none summed into another.
func (l *ToolLog) Filtered() uint64 {
	return l.filtered.Load()
}

// SetComment annotates one entry (burpsy-react-ui-5da): Burp's log comment. It re-fires the
// persistence sink so a restart keeps the comment — the sink is an upsert — and reports whether
// the id existed rather than silently keeping a comment addressed nowhere.
func (l *ToolLog) SetComment(id uint64, comment string) bool {
	l.mu.Lock()
	defer l.mu.Unlock()
	for _, e := range l.entries {
		if e.ID == id {
			e.Comment = comment
			l.fire(e)
			return true
		}
	}
	return false
}

// SetHighlight paints one entry (burpsy-react-ui-5da): Burp's row highlight, from the same
// vocabulary as the Organizer's and HTTP history's (core.ValidHighlights). Empty clears. The
// set is re-fired even when the colour is unchanged so a client re-saving reads as saved.
func (l *ToolLog) SetHighlight(id uint64, highlight string) bool {
	l.mu.Lock()
	defer l.mu.Unlock()
	for _, e := range l.entries {
		if e.ID == id {
			e.Highlight = highlight
			l.fire(e)
			return true
		}
	}
	return false
}

// fire runs the persistence and live-update hooks after an in-place annotation. Both are
// called under the log's write lock, which is what Record already does for new rows; the
// sink is an upsert, so re-writing the row is how an annotation survives a restart.
func (l *ToolLog) fire(e *Entry) {
	if l.onRecord != nil {
		l.onRecord(e)
	}
	if l.onChange != nil {
		l.onChange()
	}
}

// Record adds one entry and returns its ID, or 0 when the tool's capture is
// switched off — in which case nothing was stored and the request is gone; the
// Uncaptured counter for the tool is what says so. respLen is the response's
// byte count, or nil when no response was received — see Entry.ResponseLen for
// why the caller must choose between the two rather than defaulting to zero.
// exchange is the traffic-store exchange the bytes live under, or nil when the
// row has none to point at — see Entry.Exchange.
//
// 0 is unambiguous as the refusal marker because ids come from nextID, which
// counts *stored* rows from 1: a stored row never has id 0.
func (l *ToolLog) Record(tool Tool, host string, port uint16, tls bool, method, path string, status int, respLen *int, durMs uint64, note string, exchange *core.ExchangeID) uint64 {
	if !l.Capturing(tool) {
		if tool >= 0 && int(tool) < len(l.uncaptured) {
			l.uncaptured[tool].Add(1)
		}
		return 0
	}
	l.mu.RLock()
	keep := l.filter.matches(host, port, tls, method, path, status, l.scope)
	l.mu.RUnlock()
	if !keep {
		l.filtered.Add(1)
		return 0
	}
	id := atomic.AddUint64(&l.nextID, 1)
	// Copied rather than aliased: the length belongs to the caller, who is free to reuse or overwrite
	// it once this returns, and a logged row whose value changed after it was recorded is not a log.
	var length *int
	if respLen != nil {
		n := *respLen
		length = &n
	}
	// Same copy, same reason: the caller's exchange pointer may point into a loop variable it
	// immediately reuses, and a link that later follows the caller around is not a link.
	var ex *core.ExchangeID
	if exchange != nil {
		id := *exchange
		ex = &id
	}
	e := &Entry{
		ID:          id,
		Tool:        tool,
		Host:        host,
		Port:        port,
		TLS:         tls,
		Method:      method,
		Path:        path,
		Status:      status,
		ResponseLen: length,
		StartedMs:   uint64(time.Now().UnixMilli()),
		DurationMs:  durMs,
		Note:        note,
		Exchange:    ex,
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.entries = append(l.entries, e)
	if len(l.entries) > l.capacity {
		evict := len(l.entries) - l.capacity
		l.dropped += uint64(evict)
		l.entries = l.entries[evict:]
	}
	if l.onRecord != nil {
		l.onRecord(e)
	}
	if l.onChange != nil {
		l.onChange()
	}
	return id
}

var (
	// ToolBits masks the tool ordinal's single bit in the capturing bitmask. The
	// shifted 1 is `int64(1) << uint(tool)` per tool; encoding it per-tool keeps
	// the per-call shift off Record's hot path (Record looks up capturing via
	// Capturing, below, which still shifts — see its doc).
	ToolBits = [...]uint32{
		ToolRepeater:  1 << 0,
		ToolIntruder:  1 << 1,
		ToolScanner:   1 << 2,
		ToolSequencer: 1 << 3,
		ToolComparer:  1 << 4,
		ToolSession:   1 << 5,
		ToolDecoder:   1 << 6,
		ToolCrawler:   1 << 7,
		ToolProxy:     1 << 8,
	}
)

// Capturing reports whether the tool's requests are currently recorded.
// A single word load, meant for Record's per-send path.
func (l *ToolLog) Capturing(tool Tool) bool {
	if tool < 0 || int(tool) >= len(ToolBits) {
		return false
	}
	return l.capturing.Load()&uint32(ToolBits[tool]) != 0
}

// SetCapturing switches one tool's capture on or off. Switching off is the
// destructive act: the requests are sent and deliberately not kept, and the
// Uncaptured counter starts counting them rather than letting the log read as
// empty.
func (l *ToolLog) SetCapturing(tool Tool, on bool) {
	if tool < 0 || int(tool) >= len(ToolBits) {
		return
	}
	mask := uint32(ToolBits[tool])
	for {
		cur := l.capturing.Load()
		var next uint32
		if on {
			next = cur | mask
		} else {
			next = cur &^ mask
		}
		if l.capturing.CompareAndSwap(cur, next) {
			return
		}
	}
}

// SetAllCapturing switches every tool's capture at once. on=false is the
// nuclear "capture nothing" state; it is still reported as uncaptured counts
// rather than as an empty log.
func (l *ToolLog) SetAllCapturing(on bool) {
	var next uint32
	if on {
		next = captureAll
	}
	l.capturing.Store(next)
}

// Uncaptured reports how many requests the tool sent that capture refused.
// The counter only moves forward: clearing the log does not un-send traffic.
func (l *ToolLog) Uncaptured(tool Tool) uint64 {
	if tool < 0 || int(tool) >= len(l.uncaptured) {
		return 0
	}
	return l.uncaptured[tool].Load()
}

// UncapturedAll returns a copy of the per-tool uncaptured counters, indexed by
// the tool ordinal, for callers that project the whole axis to the wire. The
// returned slice is fresh; mutating it does not touch the log.
func (l *ToolLog) UncapturedAll() []uint64 {
	out := make([]uint64, len(l.uncaptured))
	for i := range l.uncaptured {
		out[i] = l.uncaptured[i].Load()
	}
	return out
}

// OnChange installs the signal called after the log changes, or nil to remove it.
// Single slot, so re-installing replaces rather than doubling.
//
// It carries no entry: its consumer is the live-update stream, which tells the
// browser that /api/tools/log is stale and lets that handler render the row. It
// runs under the log's write lock, on the path of every request any tool sends, so
// it must stay O(1) and allocation-light — an intruder attack at a hundred
// requests a second records a hundred entries a second.
func (l *ToolLog) OnChange(fn func()) {
	if l == nil {
		return
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.onChange = fn
}

// SetPersistenceSink installs an optional write-through hook (see the onRecord
// field doc). Call before any activity is recorded.
func (l *ToolLog) SetPersistenceSink(onRecord func(e *Entry)) {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.onRecord = onRecord
}

// Restore replaces the log's contents with a previously persisted snapshot.
// nextID resumes above the highest restored id so ids stay unique. This is the
// load path for the SQLite write-through store.
func (l *ToolLog) Restore(entries []*Entry) {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.entries = append([]*Entry{}, entries...)
	var max uint64
	for _, e := range entries {
		if e.ID >= max {
			max = e.ID + 1
		}
	}
	if max > l.nextID {
		l.nextID = max
	}
	l.dropped = 0
	for i := range l.uncaptured {
		l.uncaptured[i].Store(0)
	}
}

func (l *ToolLog) All() []*Entry {
	l.mu.RLock()
	defer l.mu.RUnlock()
	out := make([]*Entry, len(l.entries))
	copy(out, l.entries)
	return out
}

func (l *ToolLog) Count() int {
	l.mu.RLock()
	defer l.mu.RUnlock()
	return len(l.entries)
}

func (l *ToolLog) Dropped() uint64 {
	return atomic.LoadUint64(&l.dropped)
}

// Clear empties the log, keeping the nextID counter (ids stay unique).
func (l *ToolLog) Clear() {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.entries = l.entries[:0]
	if l.onChange != nil {
		l.onChange()
	}
}
